package com.example;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class PowerSet {
    public static void main(String[] args) {
        String[] set = new String[]{"a", "b", "c"};
        List<String[]> result = powerSet(set);
        System.out.println(result);
    }

    public static List<String[]> powerSet(String[] set) {
        List<String[]> result = new ArrayList<>();
        result.add(new String[0]);
        for (int i = 0; i < set.length; i++) {
            List<String[]> newSets = new ArrayList<>();
            for (String[] existingSet : result) {
                newSets.add(Arrays.copyOf(existingSet, existingSet.length + 1));
                newSets.get(newSets.size() - 1)[existingSet.length] = set[i];
            }
            result.addAll(newSets);
        }
        return result;
    }
}
