private boolean combinationSum(int[] nums, int target, int k, int n) {
    if (k == 0) return target == 0;
    if (target < k * nums[0] || target > k * nums[n - 1]) return false;
    for (int i = n - 1; i >= k - 1; --i) {
        if (nums[i] <= target && combinationSum(nums, target - nums[i], k - 1, i)) {
            return true;
        }
    }
    return false;
}

